SELECT ?place1 ?place1Label ?place2 ?place2Label ?coord1 ?coord2 ?line ?distance WHERE {
  ?place1 wdt:P31 wd:Q484170 ;
          rdfs:label ?name ;
          wdt:P625 ?coord1 .
  ?place2 wdt:P31 wd:Q484170 ;
          rdfs:label ?name ;
          wdt:P625 ?coord2 .
  FILTER(?place1 != ?place2)
  FILTER(STR(?place1) < STR(?place2))
  FILTER(LANG(?name) = "fr")
  BIND(geof:distance(?coord1, ?coord2) AS ?distance)
  BIND(CONCAT("LINESTRING(", 
        STR(geof:longitude(?coord1)), " ", STR(geof:latitude(?coord1)), ", ",
        STR(geof:longitude(?coord2)), " ", STR(geof:latitude(?coord2)), ")") AS ?wkt)
  BIND(STRDT(?wkt, geo:wktLiteral) AS ?line)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en,fr". }
}
LIMIT 1000

