SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}

SELECT ?concept ?conceptLabel (COUNT(DISTINCT ?lexeme) AS ?count) WHERE {
  ?sense wdt:P5137 ?concept .
  ?lexeme ontolex:sense ?sense .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}
GROUP BY ?concept ?conceptLabel
ORDER BY DESC(?count)
LIMIT 100

SELECT ?moon ?moonLabel ?namesake ?namesakeLabel WHERE {
  ?moon wdt:P31 wd:Q2537 .
  ?moon wdt:P138 ?namesake .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}

SELECT DISTINCT ?monument ?monumentLabel ?person ?personLabel WHERE {
  ?monument wdt:P31/wdt:P279* wd:Q4989906 ;
            wdt:P138 ?person .
  ?person wdt:P31 wd:Q5 .
  FILTER NOT EXISTS {
    ?monument ?prop ?person .
    FILTER(?prop != wdt:P138)
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}

SELECT ?language ?languageLabel WHERE {
  wd:Q55 wdt:P37 ?language .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}

SELECT DISTINCT ?party ?partyLabel WHERE {
  ?person p:P39 ?statement .
  ?statement ps:P39 ?position ;
             pq:P2937 wd:Q1322787 .
  ?person wdt:P102 ?party .
  ?position wdt:P279* wd:Q16707842 .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}

SELECT ?language ?languageLabel ?followers ?date WHERE {
  ?language wdt:P31 wd:Q9143.
  ?language p:P8687 ?statement.
  ?statement ps:P8687 ?followers.
  OPTIONAL { ?statement pq:P585 ?date. }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY DESC(?date)

SELECT ?language ?languageLabel ?code WHERE {
  ?language wdt:P31 wd:Q34770;
            wdt:P424 ?code .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}
ORDER BY ?code

SELECT DISTINCT ?type ?typeLabel WHERE {
  ?item wdt:P276 wd:Q1816874 .
  ?item wdt:P31 ?type .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}

SELECT ?astrolabe ?astrolabeLabel ?diameter ?date WHERE {
  ?astrolabe wdt:P31 wd:Q204913 ;
             wdt:P2386 ?diameter ;
             wdt:P571 ?date .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}
ORDER BY ?date

SELECT (COUNT(DISTINCT ?alphabet) AS ?count) WHERE {
  ?alphabet wdt:P282 ?writingSystem .
  ?letter wdt:P361 ?alphabet .
}

SELECT ?descendant ?descendantLabel WHERE {
  ?descendant wdt:P53 wd:Q200639 .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}

SELECT ?firstName ?firstNameLabel (COUNT(?person) AS ?count) WHERE {
  ?person wdt:P39 wd:Q3044918 .
  ?person p:P39 ?statement .
  ?statement ps:P39 wd:Q3044918 .
  FILTER NOT EXISTS { ?statement pq:P582 ?endDate . }
  ?person wdt:P735 ?firstName .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en,fr" }
}
GROUP BY ?firstName ?firstNameLabel
ORDER BY DESC(?count)

SELECT ?work ?workLabel ?date WHERE {
  ?work wdt:P50 wd:Q9068 .
  OPTIONAL { ?work wdt:P577 ?date . }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}
ORDER BY ?date

SELECT ?birthDate ?deathDate WHERE {
  wd:Q9711 wdt:P569 ?birthDate.
  wd:Q9711 wdt:P570 ?deathDate.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

SELECT ?property ?propertyLabel WHERE {
  ?property wdt:P31 wd:Q18616576 .
  ?property wdt:P1629 ?fileFormat .
  ?fileFormat wdt:P31 wd:Q235557 .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}

SELECT ?lang (COUNT(?film) AS ?count) WHERE {
  ?film wdt:P31 wd:Q11424 .
  ?article schema:about ?film ;
           schema:inLanguage ?lang ;
           schema:isPartOf ?site .
  FILTER(CONTAINS(STR(?site), "wikipedia.org"))
}
GROUP BY ?lang
ORDER BY DESC(?count)
LIMIT 10

SELECT ?topic ?topicLabel WHERE {
  ?topic wdt:P1659 wd:Q213439 .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}

SELECT ?city ?cityLabel ?population WHERE {
  ?city wdt:P31 wd:Q515 ;
        wdt:P17 wd:Q183 ;
        wdt:P1082 ?population .
  FILTER(?population > 50000)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}
ORDER BY DESC(?population)

SELECT ?country ?countryLabel ?isoCode ?flag ?fertilityRate WHERE {
  ?country wdt:P31 wd:Q6256 .
  OPTIONAL { ?country wdt:P297 ?isoCode . }
  OPTIONAL { ?country wdt:P41 ?flag . }
  OPTIONAL { ?country wdt:P4841 ?fertilityRate . }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}

SELECT ?type ?typeLabel (COUNT(?work) AS ?count) WHERE {
  ?work wdt:P31 ?type .
  ?type wdt:P279* wd:Q7725634 .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}
GROUP BY ?type ?typeLabel
ORDER BY DESC(?count)

SELECT ?decade ?place ?placeLabel (COUNT(?person) AS ?count) WHERE {
  ?person wdt:P166 ?award .
  ?award wdt:P31 wd:Q7191 .
  ?person wdt:P569 ?birthDate .
  ?person wdt:P19 ?place .
  BIND(FLOOR(YEAR(?birthDate)/10)*10 AS ?decade)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}
GROUP BY ?decade ?place ?placeLabel
ORDER BY ?decade
